"use client";
/* Donut, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Donut(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("donut"); }, []);
  return React.createElement("piix-sprite", { "name": "donut", ...piixAttrs(props) });
}

export default Donut;
